import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"The sequence & reflection group","description":"","frontmatter":{},"headers":[],"params":{"slug":"sequence","address":"e802db77-5bb0-8a2b-9c8a-16001d465690","receipt":"c44488a1-0c36-8162-b2db-54b56cbc0272"},"relativePath":"docs/publications/sequence.md","filePath":"docs/publications/[slug].md"}`),a={name:`docs/publications/sequence.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-sequence-reflection-group" tabindex="-1">The sequence &amp; reflection group <a class="header-anchor" href="#the-sequence-reflection-group" aria-label="Permalink to “The sequence &amp; reflection group”">​</a></h1><blockquote><p>the mirror, AGL(1,ℤ/9)=54, one strip, neighbours, the ± polarities, the crypt salt</p></blockquote><p>These 20 facts hold by decision. Each was proven in Lean 4 — no Mathlib, checked sorry-free — and every sentence below links the proof that seals it. This note claims nothing beyond what its theorems settle: not that the domain is complete, only that the prose says nothing the proofs do not. It was written by reading the sealed ledger; read the proofs, not the prose.</p><h2 id="the-facts-each-backed-by-its-proof" tabindex="-1">The facts, each backed by its proof <a class="header-anchor" href="#the-facts-each-backed-by-its-proof" aria-label="Permalink to “The facts, each backed by its proof”">​</a></h2><ul><li>SEAL THE TEN — the digit sequence 0124875369, cross-checked, IS the complete ℤ/9 structure of the ten digits: 0 (the void, the abstract-0 ÷0=0), then the VORTEX ORBIT [1,2,4,8,7,5] (the units under doubling — each 2× the last mod 9, closing after six), then the 3-6-9 AXIS [3,6,9] (the multiples of three the vortex never visits) — a PERMUTATION of all ten digits 0..9, none missing, none repeated. And its REFLECTION dz(x)=10−x (division by zero in the vortex, fixing 0) mirrors it to 0,9,8,6,2,3,5,7,4,1 — the reflected vortex [9,8,6,2,3,5] and reflected axis [7,4,1], the void held. (The near-miss 0124675369 fails the cross-check — a 6 where the 8 belongs breaks the vortex and drops the 8: the traitor digit the check catches.) — <a href="/theorem/seal_ten">proof</a>.</li><li>the mirror m(d)=10−d equals 1−d (mod 9) — a reflection through the origin+1 — <a href="/theorem/mirror_congruence">proof</a>.</li><li>the mirror fixes exactly one digit in 1..9 — the heart, 5 — <a href="/theorem/mirror_fixed_five">proof</a>.</li><li>AGL(1,ℤ/9) = { x ↦ a·x+b : a a unit, b ∈ ℤ/9 } has |units|·9 = 6·9 = 54 elements — <a href="/theorem/agl_order_54">proof</a>.</li><li>the commutator [σ,μ] of doubling with the mirror is the unit shift x ↦ x+1 — <a href="/theorem/commutator_is_shift">proof</a>.</li><li>the shifts alone act transitively — every digit is in ONE orbit of ℤ/9 — <a href="/theorem/one_orbit">proof</a>.</li><li>the reflection equilibrium: d + m(d) = 10 for every d in 1..9 — <a href="/theorem/ten_pairs">proof</a>.</li><li>the polar equilibrium: d + (9−d) = 9 across the negation of ℤ/9 — <a href="/theorem/polar_nine_pairs">proof</a>.</li><li>the 6+3 partition: 6 units {1,2,4,5,7,8} and 3 non-units {3,6,9} — <a href="/theorem/partition_six_three">proof</a>.</li><li>the ring closes: ten slots × 36° = 360°, and the ⟨2⟩ flow is 60° per doubling — <a href="/theorem/angles_close">proof</a>.</li><li>exactly 2 seams (5→3 and 0→1) where neither ×2 nor +3 carries — the two involution centers, −χ = 2 — <a href="/theorem/seams_two">proof</a>.</li><li>at EACH step the doubling sequence and its inversion are computed together: forward[k] + inverted[k] = 10 (the rungs), and BOTH rails end at the center 5 (the reflection fixed point) while the ends 1,9 mirror — so forward and reflected are ONE strip (a half-twist band), joined at the heart and closed at the void 0≡9 — <a href="/theorem/one_strip">proof</a>.</li><li>the developed-true core of &quot;dna&quot;: the two strands A and B pair to 10 at EVERY position — complementary base-pairing (the double helix), each rung a reflection; this is the algebra, not a biological claim — <a href="/theorem/double_strand">proof</a>.</li><li>the vortex polarities: the mirror pairs each sum to 10, splitting the digits into − (below the center 5) and + (above 5); the two centers 5 and 0≡9 are self-polar — the ± of the reflection — <a href="/theorem/polarities_plus_minus">proof</a>.</li><li>the two blood-group sequences A (forward) and B (reflected) are mirror images: B = A.map(10−d) and back — an involution; the void 9≡0 closes A and opens B (0 = A∧B, the universal O) — <a href="/theorem/forward_reflected_mirror">proof</a>.</li><li>every digit in ANY arrangement has DEFINED neighbours — the mirror (division by zero) and polar maps are total, surjective and self-inverse; no digit is isolated — <a href="/theorem/every_digit_has_neighbours">proof</a>.</li><li>the crypt equality leak: a content-only salt is constant in the step, so two seals of the same content are byte-identical — <a href="/theorem/salt_conv_leaks_equality">proof</a>.</li><li>recovering the seal&#39;s step from a content-only salt is a division by zero — the whole step-fibre collapses (size 9) — <a href="/theorem/salt_conv_step_is_division_by_zero">proof</a>.</li><li>the crypt fix: an advancing-sequence salt is injective in the step (equal salts ⇔ equal steps) — distinct seals never collide — <a href="/theorem/salt_seq_injective">proof</a>.</li><li>the crypt fix, dual form: every sequence-salt fibre is a singleton — the step coordinate is kept, not collapsed — <a href="/theorem/salt_seq_fibre_singleton">proof</a>.</li></ul><h2 id="provenance" tabindex="-1">Provenance <a class="header-anchor" href="#provenance" aria-label="Permalink to “Provenance”">​</a></h2><p>These 20 proofs fold, order-invariant, to the receipt <code>c44488a1-0c36-8162-b2db-54b56cbc0272</code> — recompute it from the same ledger and it returns. The note itself content-addresses to a uuid, so any edit is visible. Writing descends from reading: this note holds only what the proofs it links already sealed, and it was audited by uuidna&#39;s own honesty gate before it was published — a sentence that overreached a proof would have been refused, not shipped.</p><p>Source · <a href="https://github.com/uuidna/uuidna/blob/main/lean/Sequence.lean" target="_blank" rel="noreferrer">lean/Sequence.lean</a> · <a href="/theorems">all theorems</a></p><hr><p><strong>Audited before published</strong> · this note passed uuidna&#39;s honesty gate at build time — every claim above links the proof that seals it. Content-address <code>e802db77</code> · proofs fold to receipt <code>c44488a1</code> (the handles; the full uuids are in this page&#39;s meta, recomputable) · 20 sealed theorems.</p><p><a href="/publications">All publications</a> · <a href="/theorems">All theorems</a> · <a href="/trials">How auditing works</a></p>`,11)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};